// Gimmick items are stage finds, not crafts (DESIGN.md §4.3/§4.6): once a player reaches the unlocking stage they
// turn up in structure chests (loot modifiers generated by tools/gen_finds.py). Crafting can't check who is
// crafting in 1.21, so every other way to make them is removed here; the stonecutter only swaps between looks.

// Members of Mega Showdown 1.3.3's #mega_showdown:mega_bracelet and #mega_showdown:z_ring tags (first = reward item)
const MEGA_BRACELETS = [
  'mega_showdown:mega_bracelet', 'mega_showdown:mega_bracelet_red', 'mega_showdown:mega_bracelet_yellow',
  'mega_showdown:mega_bracelet_pink', 'mega_showdown:mega_bracelet_green', 'mega_showdown:mega_bracelet_blue',
  'mega_showdown:mega_bracelet_black', 'mega_showdown:may_bracelet', 'mega_showdown:mega_ring',
  'mega_showdown:lysandre_ring', 'mega_showdown:brendan_mega_cuff', 'mega_showdown:korrina_glove',
  'mega_showdown:maxie_glasses', 'mega_showdown:archie_anchor', 'mega_showdown:diantha_mega_charm',
  'mega_showdown:zinnia_mega_anklet', 'mega_showdown:lisia_mega_tiara',
]
const Z_RINGS = [
  'mega_showdown:z_ring', 'mega_showdown:z_ring_black', 'mega_showdown:z_ring_yellow', 'mega_showdown:z_ring_green',
  'mega_showdown:z_ring_blue', 'mega_showdown:z_ring_pink', 'mega_showdown:z_ring_red', 'mega_showdown:olivias_z_ring',
  'mega_showdown:hapus_z_ring', 'mega_showdown:z_power_ring', 'mega_showdown:olivia_z_power_ring',
  'mega_showdown:hapu_z_power_ring', 'mega_showdown:rocket_z_power_ring', 'mega_showdown:gladion_z_power_ring',
  'mega_showdown:nanu_z_power_ring',
]

ServerEvents.recipes(event => {
  // Enablers come only from stage rewards
  event.remove({ output: '#mega_showdown:mega_bracelet' })
  event.remove({ output: '#mega_showdown:z_ring' })
  event.remove({ output: '#mega_showdown:tera_orb' })
  event.remove({ output: '#mega_showdown:dynamax_band' })
  event.remove({ output: '#mega_showdown:omni_ring' })
  // Stage 8 finds (Cobblemon brews the capsule, Mega Showdown crafts the patch)
  event.remove({ output: 'cobblemon:ability_capsule' })
  event.remove({ output: 'cobblemon:ability_patch' })
  // The Master Ball is only ever the Champion's reward (Cobblemon ships a netherite/Nether Star recipe)
  event.remove({ output: 'cobblemon:master_ball' })

  // Cosmetic swaps: any bracelet/ring look from the base one and back, at a stonecutter
  let lookSets = [MEGA_BRACELETS, Z_RINGS]
  lookSets.forEach(looks => {
    let base = looks[0]
    for (let i = 1; i < looks.length; i++) {
      event.recipes.minecraft.stonecutting(looks[i], base).id(`campfiremons:looks/${looks[i].split(':')[1]}`)
      event.recipes.minecraft.stonecutting(base, looks[i]).id(`campfiremons:looks/${looks[i].split(':')[1]}_to_base`)
    }
  })

  // The Omni Ring does every gimmick from one slot, so it costs all four enablers (all owned only from Stage 7)
  event.recipes.minecraft.crafting_shapeless('mega_showdown:omni_ring', [
    '#mega_showdown:mega_bracelet', '#mega_showdown:z_ring', 'mega_showdown:tera_orb', 'mega_showdown:dynamax_band',
  ]).id('campfiremons:omni_ring')
})
